    public WhiteAngelStatueModel(ModelPart root) {
        this.root = root;
        this.allParts = root.getAllParts().toList();   // once: restPose runs every frame for every unit
        collect(root);
    }

    /** The tree's named parts, by their generated paths (no lookups by search at run time). */
    private void collect(ModelPart root) {
        bones.put("body", root.getChild("body"));
        bones.put("wing_left", root.getChild("body").getChild("wing_left"));
        bones.put("wing_right", root.getChild("body").getChild("wing_right"));
        bones.put("head", root.getChild("body").getChild("head"));
        lodParts.add(root.getChild("body").getChild("head").getChild("lod"));
        bones.put("halo", root.getChild("body").getChild("head").getChild("halo"));
        lodParts.add(root.getChild("body").getChild("head").getChild("halo").getChild("lod"));
        bones.put("sword", root.getChild("body").getChild("sword"));
        lodParts.add(root.getChild("body").getChild("sword").getChild("lod"));
        bones.put("hands", root.getChild("body").getChild("hands"));
        lodParts.add(root.getChild("body").getChild("hands").getChild("lod"));
        bones.put("left_arm", root.getChild("body").getChild("left_arm"));
        bones.put("left_fore", root.getChild("body").getChild("left_arm").getChild("left_fore"));
        bones.put("right_arm", root.getChild("body").getChild("right_arm"));
        bones.put("right_fore", root.getChild("body").getChild("right_arm").getChild("right_fore"));
        
    }

    @Override
    public List<ModelPart> teamParts() {
        return teamParts;
    }

    @Override
    public List<ModelPart> glowParts() {
        return glowParts;
    }

    @Override
    public void drawOnly(List<ModelPart> keep) {
        for (int i = 0, n = allParts.size(); i < n; i++)
            allParts.get(i).skipDraw = true;
        for (int i = 0, n = keep.size(); i < n; i++)
            keep.get(i).skipDraw = false;
    }

    @Override
    public void drawAll() {
        for (int i = 0, n = allParts.size(); i < n; i++)
            allParts.get(i).skipDraw = false;
    }

    public ModelPart bone(String name) {
        return bones.get(name);
    }

    /** Bone name -> its parent bone ("" for a bone on the root). */
    public static final Map<String, String> PARENTS = Map.ofEntries(Map.entry("body", ""),
        Map.entry("wing_left", "body"),
        Map.entry("wing_right", "body"),
        Map.entry("head", "body"),
        Map.entry("halo", "head"),
        Map.entry("sword", "body"),
        Map.entry("hands", "body"),
        Map.entry("left_arm", "body"),
        Map.entry("left_fore", "left_arm"),
        Map.entry("right_arm", "body"),
        Map.entry("right_fore", "right_arm"));

    /**
     * A bone and its ancestors, root side first: apply translateAndRotate of all but the last, then render the last,
     * to draw one bone where it stands in the whole body (an additive glow pass over a held weapon, say).
     */
    public ModelPart[] path(String name) {
        List<ModelPart> out = new ArrayList<>();
        for (String b = name; b != null && !b.isEmpty(); b = PARENTS.get(b)) {
            ModelPart p = bones.get(b);
            if (p == null)
                return new ModelPart[0];
            out.add(0, p);
        }
        return out.toArray(new ModelPart[0]);
    }

